const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // Load country boundaries from the FAO GAUL dataset
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const cambodiaGeom = countries.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia')).geometry();
  const vietnamGeom = countries.filter(ee.Filter.eq('ADM0_NAME', 'Viet Nam')).geometry();

  // 2. Data Acquisition & Check
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
      .select('MaxFRP') // Select a band to make it an image collection
      .filterDate(startDate, endDate);

  // Convert ImageCollection to FeatureCollection for counting points
  const firePoints = fireCollection.map(function(image) {
    return image.gt(0).selfMask().reduceToVectors({
      geometry: image.geometry(),
      scale: 1000, // MODIS fire pixel scale
      geometryType: 'centroid',
      eightConnected: false,
    });
  }).flatten();

  if (firePoints.size().getInfo() === 0) {
    console.log("No fire data found for the entire period.");
    console.log("A"); // The question is 'did Cambodia have more', if both are 0, the answer is No. But if the collection is empty, that's a C1.
    return;
  }

  // 3. Processing: Filter fire points by country
  const firesCambodia = firePoints.filterBounds(cambodiaGeom);
  const firesVietnam = firePoints.filterBounds(vietnamGeom);

  // 4. Calculation: Get the count of fire detections for each country
  const countCambodia = firesCambodia.size().getInfo();
  const countVietnam = firesVietnam.size().getInfo();

  // 5. Validation & Final Answer
  console.log(`Time Period: ${startDate} to ${endDate}`);
  console.log(`Cambodia Active Fire Detections: ${countCambodia}`);
  console.log(`Vietnam Active Fire Detections: ${countVietnam}`);

  if (countCambodia === null || countVietnam === null) {
      console.log("Could not compute fire counts.");
      console.log("C3");
  } else if (countCambodia > countVietnam) {
      console.log("Evidence: Cambodia had more fire detections than Vietnam.");
      console.log("A");
  } else {
      console.log("Evidence: Cambodia did not have more fire detections than Vietnam.");
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during the analysis.");
